create temporary table coupon_feature_results(result jsonb);
do $test$
declare admin_id uuid; owner_id uuid; staff_id uuid; campaign_id uuid:=gen_random_uuid(); future_id uuid:=gen_random_uuid(); image text:=gen_random_uuid()||'.jpg'; payload jsonb; code text; cid uuid; r jsonb; before_hash text; results jsonb:='[]';
begin
 select u.id into admin_id from auth.users u join public.admin_accounts a on lower(u.email)=a.email where a.is_active limit 1;
 select u.id into owner_id from auth.users u where u.deleted_at is null and not exists(select 1 from public.admin_accounts a where a.email=lower(u.email) and a.is_active) order by u.id limit 1;
 select u.id into staff_id from auth.users u where u.deleted_at is null and u.id<>owner_id and not exists(select 1 from public.admin_accounts a where a.email=lower(u.email) and a.is_active) order by u.id limit 1;
 assert admin_id is not null and owner_id is not null and staff_id is not null;
 select md5(coalesce(jsonb_agg(to_jsonb(u) order by id)::text,'')) into before_hash from public.user_coupons u;
 begin
  insert into storage.objects(bucket_id,name,metadata) values('coupon-benefits',image,'{"mimetype":"image/jpeg","size":100}');
  payload:=jsonb_build_object('title','TRANSACTION-ONLY-COUPON-QA','benefit_text','Gift x 1','image_path',image,'starts_at',now()-interval '1 hour','ends_at',now()+interval '1 day','instructions','Staff confirmation required','shop_name','QA shop','issuance_limit',2,'staff_user_ids',jsonb_build_array(staff_id));
  perform set_config('request.jwt.claim.sub',owner_id::text,true);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated')::text,true);
  begin perform public.admin_create_coupon_campaign(campaign_id,payload);raise exception 'Customer created campaign';exception when insufficient_privilege then results:=results||' ["customer campaign creation denied"]'::jsonb;end;
  perform set_config('role','authenticated',true);
  begin insert into storage.objects(bucket_id,name) values('coupon-benefits',gen_random_uuid()||'.jpg');raise exception 'Customer image upload allowed';exception when insufficient_privilege then null;end;
  perform set_config('role','postgres',true);
  perform set_config('request.jwt.claim.sub',admin_id::text,true);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true);
  perform set_config('role','authenticated',true);
  insert into storage.objects(bucket_id,name,metadata) values('coupon-benefits',gen_random_uuid()||'.jpg','{"mimetype":"image/jpeg","size":100}');
  begin delete from storage.objects where bucket_id='coupon-benefits' and name=image;exception when insufficient_privilege then null;end;
  assert exists(select 1 from storage.objects where bucket_id='coupon-benefits' and name=image);
  perform set_config('role','postgres',true);
  results:=results||'["customer image insert denied; admin image insert allowed; image deletion denied"]';
  assert public.admin_create_coupon_campaign(campaign_id,payload)=campaign_id;
  assert public.admin_create_coupon_campaign(campaign_id,payload)=campaign_id;
  assert (select count(*)=1 from public.coupon_campaigns where id=campaign_id);
  begin perform public.admin_create_coupon_campaign(campaign_id,payload||'{"title":"changed"}');raise exception using errcode='ZX002',message='changed retry accepted';exception when sqlstate 'P0001' then null;end;
  results:=results||'["admin create succeeds; same request replay is idempotent; altered replay rejected"]';
  r:=public.admin_issue_coupon_campaign(campaign_id,array[owner_id,owner_id]);assert (r->>'issued')::int=1;
  r:=public.admin_issue_coupon_campaign(campaign_id,array[owner_id]);assert (r->>'issued')::int=0 and (r->>'skipped')::int=1;
  select id,u.code into cid,code from public.user_coupons u where source_id=campaign_id and user_id=owner_id;
  assert code ~ '^FP-[A-F0-9]{20}$';
  assert (select metadata->>'usage_instructions'='Staff confirmation required' and metadata->>'benefit_image_url' like '%coupon-benefits/%' from public.user_coupons where id=cid);
  r:=public.admin_issue_coupon_campaign(campaign_id,array[staff_id]);assert (r->>'issued')::int=1;
  begin perform public.admin_issue_coupon_campaign(campaign_id,array[admin_id]);raise exception using errcode='ZX002',message='cap exceeded';exception when sqlstate 'P0001' then null;end;
  assert (select count(*)=2 from public.user_coupons where source_id=campaign_id);
  results:=results||'["deduplicated member issuance; replay skipped; snapshot saved; cap enforced atomically"]';
  perform set_config('request.jwt.claim.sub',owner_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated')::text,true);
  begin perform public.redeem_staff_coupon(code);raise exception 'Customer redeemed';exception when insufficient_privilege then null;end;
  begin perform public.inspect_staff_coupon(code);raise exception 'Customer inspected staff data';exception when insufficient_privilege then null;end;
  begin perform public.admin_issue_coupon_campaign(campaign_id,array[owner_id]);raise exception 'Customer issued';exception when insufficient_privilege then null;end;
  perform set_config('role','authenticated',true);
  assert (select count(*)=1 from public.user_coupons where source_id=campaign_id);
  assert (select count(*)=0 from public.coupon_campaigns where id=campaign_id);
  perform set_config('role','postgres',true);
  results:=results||'["customer self redemption / staff lookup / issuance denied; own-only coupon RLS; campaign hidden"]';
  perform set_config('request.jwt.claim.sub',staff_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',staff_id,'role','authenticated')::text,true);
  assert (public.inspect_staff_coupon(code)->>'can_redeem')::boolean;
  assert public.redeem_staff_coupon(code)=true;
  assert public.redeem_staff_coupon(code)=false;
  assert public.redeem_staff_coupon(code)=false;
  assert (public.inspect_staff_coupon(code)->>'status')='used';
  begin perform public.redeem_staff_coupon((select u.code from public.user_coupons u where source_id=campaign_id and user_id=staff_id));raise exception 'Staff redeemed own coupon';exception when insufficient_privilege then null;end;
  results:=results||'["assigned staff redeems once; duplicate/retry rejected; staff own redemption denied"]';
  perform set_config('request.jwt.claim.sub',admin_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true);
  assert not public.admin_cancel_issued_coupon(cid,'cannot cancel used');
  assert public.admin_cancel_issued_coupon((select id from public.user_coupons where source_id=campaign_id and user_id=staff_id),'QA cancel');
  assert (public.admin_list_issued_coupons(campaign_id,0)->0) is not null;
  assert public.admin_set_coupon_campaign_active(campaign_id,false);
  r:=public.admin_issue_coupon_campaign(campaign_id,array[owner_id]);assert (r->>'issued')::int=0;
  results:=results||'["used cancellation denied; unused cancellation recorded; history readable; replay safe after pause"]';
  assert public.admin_update_coupon_staff(campaign_id,'{}'::uuid[]);
  assert public.admin_update_coupon_staff(campaign_id,'{}'::uuid[]);
  assert (select jsonb_array_length(staff_change_history)=1 from public.coupon_campaigns where id=campaign_id);
  perform set_config('request.jwt.claim.sub',staff_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',staff_id,'role','authenticated')::text,true);
  begin perform public.inspect_staff_coupon(code);raise exception 'Removed staff still has access';exception when insufficient_privilege then null;end;
  perform set_config('request.jwt.claim.sub',admin_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true);
  results:=results||'["staff removal immediately enforced; repeat update idempotent; permission history retained"]';
  payload:=payload||jsonb_build_object('starts_at',now()+interval '1 day','ends_at',now()+interval '2 days','issuance_limit',5);
  assert public.admin_create_coupon_campaign(future_id,payload)=future_id;
  perform public.admin_issue_coupon_campaign(future_id,array[owner_id]);
  select u.code into code from public.user_coupons u where source_id=future_id;
  assert public.redeem_staff_coupon(code)=false;
  update public.coupon_campaigns set starts_at=now()-interval '2 days',ends_at=now()-interval '1 day' where id=future_id;
  update public.user_coupons set expires_at=now()-interval '1 day' where source_id=future_id;
  assert public.redeem_staff_coupon(code)=false;
  results:=results||'["before-start and expired redemption denied"]';
  perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{}',true);
  begin perform public.redeem_staff_coupon(code);raise exception 'Anonymous redemption';exception when insufficient_privilege then null;end;
  assert not has_function_privilege('anon','public.redeem_staff_coupon(text)','execute');
  assert not has_function_privilege('anon','public.admin_issue_coupon_campaign(uuid,uuid[])','execute');
  assert not has_table_privilege('authenticated','public.coupon_campaigns','update');
  results:=results||'["anonymous denied; no direct campaign update"]';
  raise exception using errcode='ZX001',message='rollback all QA data and notification inserts';
 exception when sqlstate 'ZX001' then null;
 end;
 assert not exists(select 1 from public.coupon_campaigns where id in(campaign_id,future_id));
 assert not exists(select 1 from storage.objects where bucket_id='coupon-benefits' and name=image);
 assert before_hash=(select md5(coalesce(jsonb_agg(to_jsonb(u) order by id)::text,'')) from public.user_coupons u);
 results:=results||'["all fixtures including notifications rolled back; preexisting coupons unchanged"]';
 insert into coupon_feature_results values(results);
end $test$;
select * from coupon_feature_results;
